#!/usr/bin/env python3
"""Exact centre of the Lie algebra generated by localStep's operators L_t = I + e_t 1^T.

The claim under test: Z(g) = 0, i.e. there is NO central element, hence no candidate
for the role d_tau plays in {Q,Q} = d_tau (where d_tau IS central).
A centre of dimension >= 1 would refute the claim. Checked for several dimensions D.
"""
from fractions import Fraction
import itertools


def gens(D):
    L = []
    for t in range(D):
        M = [[Fraction(1 if i == j else 0) for j in range(D)] for i in range(D)]
        for j in range(D):
            M[t][j] += 1
        L.append(M)
    return L


def mul(A, B):
    n = len(A)
    return [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(n)] for i in range(n)]


def comm(A, B):
    P, Q = mul(A, B), mul(B, A)
    return [[P[i][j] - Q[i][j] for j in range(len(A))] for i in range(len(A))]


def rank_rows(rows):
    M = [r[:] for r in rows]
    if not M:
        return 0
    n, m = len(M), len(M[0])
    r = 0
    for c in range(m):
        piv = next((i for i in range(r, n) if M[i][c] != 0), None)
        if piv is None:
            continue
        M[r], M[piv] = M[piv], M[r]
        pv = M[r][c]
        M[r] = [x / pv for x in M[r]]
        for i in range(n):
            if i != r and M[i][c] != 0:
                f = M[i][c]
                M[i] = [a - f * b for a, b in zip(M[i], M[r])]
        r += 1
    return r


for D in (2, 3, 4, 5, 6):
    L = gens(D)
    basis = L  # verified below to be closed under bracket
    flat = [[x for row in M for x in row] for M in basis]
    dim_g = rank_rows(flat)

    # closure: every bracket lies in span(basis)?
    closed = True
    for A, B in itertools.combinations(basis, 2):
        C = comm(A, B)
        cflat = [x for row in C for x in row]
        if rank_rows(flat + [cflat]) != dim_g:
            closed = False
    # derived subalgebra
    der = [[x for row in comm(A, B) for x in row] for A, B in itertools.combinations(basis, 2)]
    dim_der = rank_rows(der)

    # centre: solve sum_t c_t L_t commutes with every L_k
    # unknowns c_0..c_{D-1}; equations from each entry of [sum c_t L_t, L_k]
    eqs = []
    for k in range(D):
        # entry-wise linear form in c
        for i in range(D):
            for j in range(D):
                row = []
                for t in range(D):
                    row.append(comm(L[t], L[k])[i][j])
                eqs.append(row)
    dim_centre = D - rank_rows(eqs)

    print(f"D={D}: dim g = {dim_g:>2}  closed under bracket = {closed}  "
          f"dim [g,g] = {dim_der:>2}  dim Z(g) = {dim_centre}   "
          f"[predicted: dim g = D = {D}, dim [g,g] = D-1 = {D-1}, dim Z(g) = 0]")
